import json
import os

# Table definitions from query
tables_json = """[{"table_name":"barangay","create_statement":"CREATE TABLE public.barangay (\\n  brgy_name text NOT NULL,\\n  brgy_id uuid NOT NULL DEFAULT gen_random_uuid(),\\n  city_id uuid NOT NULL\\n);"},{"table_name":"building","create_statement":"CREATE TABLE public.building (\\n  bldg_name text,\\n  bldg_id uuid NOT NULL DEFAULT gen_random_uuid(),\\n  street_id uuid NOT NULL\\n);"},{"table_name":"chat_flows_v2","create_statement":"CREATE TABLE public.chat_flows_v2 (\\n  flow_id text NOT NULL,\\n  flow_definition jsonb NOT NULL,\\n  active boolean DEFAULT true,\\n  created_at timestamptz DEFAULT now(),\\n  updated_at timestamptz DEFAULT now(),\\n  flow_owner text DEFAULT 'customer'::text\\n);"},{"table_name":"chat_messages_v2","create_statement":"CREATE TABLE public.chat_messages_v2 (\\n  message_id uuid NOT NULL DEFAULT gen_random_uuid(),\\n  session_id uuid,\\n  sender_role text NOT NULL,\\n  message_text_enc bytea NOT NULL,\\n  sent_at timestamptz DEFAULT now(),\\n  metadata jsonb DEFAULT '{}'::jsonb\\n);"},{"table_name":"chat_session_feedback","create_statement":"CREATE TABLE public.chat_session_feedback (\\n  feedback_id uuid NOT NULL DEFAULT gen_random_uuid(),\\n  session_id uuid NOT NULL,\\n  customer_id uuid NOT NULL,\\n  rating integer NOT NULL,\\n  submitted_at timestamptz NOT NULL DEFAULT now(),\\n  user_role text NOT NULL\\n);"},{"table_name":"chat_sessions_v2","create_statement":"CREATE TABLE public.chat_sessions_v2 (\\n  session_id uuid NOT NULL DEFAULT gen_random_uuid(),\\n  flow_id text,\\n  customer_id uuid NOT NULL,\\n  status text DEFAULT 'active'::text,\\n  created_at timestamptz DEFAULT now(),\\n  ended_at timestamptz,\\n  metadata jsonb DEFAULT '{}'::jsonb,\\n  inquiry_id uuid,\\n  quote_id uuid,\\n  display_title text,\\n  order_id uuid\\n);"},{"table_name":"city","create_statement":"CREATE TABLE public.city (\\n  city_name text NOT NULL,\\n  city_id uuid NOT NULL DEFAULT gen_random_uuid(),\\n  province_id uuid NOT NULL\\n);"},{"table_name":"customer","create_statement":"CREATE TABLE public.customer (\\n  customer_id uuid NOT NULL,\\n  first_name varchar DEFAULT ''::character varying,\\n  last_name varchar DEFAULT ''::character varying,\\n  contact_no varchar DEFAULT ''::character varying,\\n  email_address varchar DEFAULT ''::character varying,\\n  customer_type varchar DEFAULT ''::character varying,\\n  location_id uuid NOT NULL,\\n  gender varchar(20),\\n  birthday date\\n);"},{"table_name":"deliveries","create_statement":"CREATE TABLE public.deliveries (\\n  delivery_id bigint NOT NULL,\\n  order_id varchar,\\n  retrieval_status varchar,\\n  delivered_datetime timestamp\\n);"},{"table_name":"inquiries_v2","create_statement":"CREATE TABLE public.inquiries_v2 (\\n  inquiry_id uuid NOT NULL DEFAULT gen_random_uuid(),\\n  inquiry_type text,\\n  inquiry_status text DEFAULT 'new'::text,\\n  customer_id uuid NOT NULL,\\n  session_id uuid,\\n  order_id uuid,\\n  display_id varchar(20),\\n  received_at timestamptz NOT NULL DEFAULT now(),\\n  updated_at timestamptz NOT NULL DEFAULT now(),\\n  resolved_at timestamptz,\\n  updated_by uuid\\n);"},{"table_name":"location","create_statement":"CREATE TABLE public.location (\\n  location_id uuid NOT NULL,\\n  bldg_id uuid NOT NULL,\\n  zip_code numeric,\\n  zip_id uuid\\n);"},{"table_name":"notifications","create_statement":"CREATE TABLE public.notifications (\\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\\n  customer_id uuid NOT NULL,\\n  source_type text,\\n  source_id uuid,\\n  title text NOT NULL,\\n  message text NOT NULL,\\n  is_read boolean DEFAULT false,\\n  created_at timestamptz DEFAULT now(),\\n  read_at timestamptz,\\n  type text DEFAULT 'info'::text,\\n  category text DEFAULT 'system'::text\\n);"},{"table_name":"orders","create_statement":"CREATE TABLE public.orders (\\n  order_id uuid NOT NULL DEFAULT gen_random_uuid(),\\n  customer_id uuid NOT NULL,\\n  order_specs jsonb NOT NULL DEFAULT '{}'::jsonb,\\n  total_amount numeric NOT NULL,\\n  status text NOT NULL DEFAULT 'awaiting_payment'::text,\\n  payment_proof text,\\n  payment_verified_at timestamptz,\\n  payment_verified_by uuid,\\n  created_at timestamptz NOT NULL DEFAULT now(),\\n  updated_at timestamptz NOT NULL DEFAULT now(),\\n  completed_at timestamptz,\\n  display_id varchar(20),\\n  payment_proof_uploaded_at timestamptz,\\n  quote_id uuid,\\n  proposal_id uuid,\\n  session_id uuid,\\n  payment_denied_by uuid,\\n  payment_denied_at timestamptz,\\n  denial_reason text,\\n  updated_by uuid,\\n  service_id uuid\\n);"},{"table_name":"payment_methods","create_statement":"CREATE TABLE public.payment_methods (\\n  method_id uuid NOT NULL DEFAULT gen_random_uuid(),\\n  method_type text NOT NULL,\\n  image_url text NOT NULL,\\n  label text NOT NULL,\\n  is_active boolean NOT NULL DEFAULT true,\\n  display_order integer NOT NULL DEFAULT 0,\\n  created_at timestamptz NOT NULL DEFAULT now(),\\n  updated_at timestamptz NOT NULL DEFAULT now()\\n);"},{"table_name":"payments","create_statement":"CREATE TABLE public.payments (\\n  payment_id varchar NOT NULL,\\n  order_id varchar,\\n  quote_id bigint,\\n  payment_amount float8,\\n  payment_status varchar DEFAULT 'Not Paid'::character varying,\\n  payment_method varchar,\\n  paid_datetime timestamp\\n);"},{"table_name":"printing_services","create_statement":"CREATE TABLE public.printing_services (\\n  service_id uuid NOT NULL DEFAULT gen_random_uuid(),\\n  display_id varchar(20),\\n  service_name text NOT NULL,\\n  category_id uuid NOT NULL,\\n  description text,\\n  status text NOT NULL,\\n  created_at timestamptz DEFAULT now(),\\n  created_by uuid,\\n  updated_at timestamptz DEFAULT now(),\\n  updated_by uuid\\n);"},{"table_name":"province","create_statement":"CREATE TABLE public.province (\\n  province_name text NOT NULL,\\n  region_id uuid NOT NULL,\\n  province_id uuid NOT NULL DEFAULT gen_random_uuid()\\n);"},{"table_name":"quote_proposals","create_statement":"CREATE TABLE public.quote_proposals (\\n  proposal_id uuid NOT NULL DEFAULT gen_random_uuid(),\\n  spec_id uuid NOT NULL,\\n  spec_final jsonb NOT NULL DEFAULT '{}'::jsonb,\\n  quoted_price numeric NOT NULL,\\n  notes text,\\n  created_at timestamptz NOT NULL DEFAULT now(),\\n  updated_at timestamptz NOT NULL DEFAULT now(),\\n  sent_at timestamptz,\\n  session_id uuid NOT NULL\\n);"},{"table_name":"quote_specs","create_statement":"CREATE TABLE public.quote_specs (\\n  spec_id uuid NOT NULL DEFAULT gen_random_uuid(),\\n  spec_data jsonb NOT NULL DEFAULT '{}'::jsonb,\\n  created_at timestamptz NOT NULL DEFAULT now(),\\n  session_id uuid NOT NULL\\n);"},{"table_name":"quotes","create_statement":"CREATE TABLE public.quotes (\\n  quote_id uuid NOT NULL DEFAULT gen_random_uuid(),\\n  customer_id uuid NOT NULL,\\n  session_id uuid NOT NULL,\\n  status text NOT NULL DEFAULT 'active'::text,\\n  created_at timestamptz NOT NULL DEFAULT now(),\\n  updated_at timestamptz NOT NULL DEFAULT now(),\\n  ended_at timestamptz,\\n  display_id varchar(20),\\n  updated_by uuid,\\n  proposal_id uuid\\n);"},{"table_name":"region","create_statement":"CREATE TABLE public.region (\\n  region_id uuid NOT NULL,\\n  region_name varchar NOT NULL\\n);"},{"table_name":"service_categories","create_statement":"CREATE TABLE public.service_categories (\\n  category_id uuid NOT NULL DEFAULT gen_random_uuid(),\\n  category_name text NOT NULL,\\n  description text,\\n  display_order integer DEFAULT 0,\\n  is_active boolean DEFAULT true,\\n  created_at timestamptz DEFAULT now(),\\n  updated_at timestamptz DEFAULT now()\\n);"},{"table_name":"street","create_statement":"CREATE TABLE public.street (\\n  street_name text NOT NULL,\\n  street_id uuid NOT NULL DEFAULT gen_random_uuid(),\\n  brgy_id uuid NOT NULL\\n);"}]"""

tables_data = json.loads(tables_json)

os.makedirs('supabase/tables', exist_ok=True)

# Write table files
table_count = 0
for table_data in tables_data:
    table_name = table_data['table_name']
    create_stmt = table_data['create_statement'].replace('\\n', '\n')
    
    filename = f"{table_name}.sql"
    filepath = os.path.join('supabase/tables', filename)
    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(create_stmt)
    table_count += 1

print(f"Created {table_count} table files in supabase/tables")

